package main

import (
	"fmt"
	"strings"
)

func main() {
	raw := "  Go, go , 标准库 , Go "
	parts := strings.Split(raw, ",")
	cleaned := make([]string, 0, len(parts))
	for _, part := range parts {
		// 字符串不可变，ToLower/TrimSpace 都返回新串，必须接住结果。
		item := strings.ToLower(strings.TrimSpace(part))
		if item != "" {
			cleaned = append(cleaned, item)
		}
	}

	fmt.Println("标签:", strings.Join(cleaned, "|"))
	fmt.Println("首个标签以 go 开头:", strings.HasPrefix(cleaned[0], "go"))
	fmt.Println("go 出现的次数:", strings.Count(strings.Join(cleaned, ","), "go"))
	fmt.Println("替换标准库:", strings.ReplaceAll(strings.Join(cleaned, ","), "标准库", "stdlib"))
}

