package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	raw := "90, 85 ,abc,100"
	total, valid := 0, 0
	for _, part := range strings.Split(raw, ",") {
		// Atoi 不认识空格，先 TrimSpace；转换失败时返回错误而不是崩溃。
		score, err := strconv.Atoi(strings.TrimSpace(part))
		if err != nil {
			fmt.Println("跳过无效分数:", part)
			continue
		}
		total += score
		valid++
	}
	fmt.Println("有效个数:", valid)
	fmt.Println("总分:", total)
	fmt.Println("平均分:", strconv.Itoa(total/valid))
	fmt.Println("是否优秀:", strconv.FormatBool(total/valid >= 90))
}

