package main

import (
	"fmt"
	"math"
)

func main() {
	// 时长换算与 time.Duration 的整数纳秒换算同构：
	// 练习环境不能 import time，这一节用数学运算做替代练习。
	total := 3800
	fmt.Println("时长:", total/3600, "时", total%3600/60, "分", total%60, "秒")

	// 变量参与运算才会暴露浮点误差，先四舍五入到"分"再比较。
	a, b := 0.1, 0.2
	sum := math.Round((a+b)*100) / 100
	fmt.Println("金额:", sum, "等于 0.3:", sum == 0.3)

	// Floor 向下取整，Ceil 向上取整，Round 四舍五入到最近整数。
	x := 2.4
	fmt.Println("取整:", math.Floor(x), math.Ceil(x), math.Round(x))
	fmt.Println("开方与绝对值:", math.Sqrt(16), math.Abs(-3.5))
	fmt.Println("区间夹取:", math.Max(3, math.Min(7, 10)))
}

