package main

import (
	"fmt"
	"strconv"
	"strings"
)

// 每条记录用分号分隔、字段是「姓名,分数」，可能夹带空格或整行是坏数据。
func main() {
	raw := "小明,88; 小红 , 95 ;小刚,79;错误行"
	total, count, best, bestName := 0, 0, 0, ""
	for _, line := range strings.Split(raw, ";") {
		line = strings.TrimSpace(line)
		fields := strings.Split(line, ",")
		if len(fields) != 2 { fmt.Println("跳过坏行:", line); continue }
		name := strings.TrimSpace(fields[0])
		score, err := strconv.Atoi(strings.TrimSpace(fields[1]))
		if err != nil { fmt.Println("跳过坏行:", line); continue }
		total += score
		count++
		if score > best {
			best, bestName = score, name
		}
	}
	fmt.Println("有效人数:", count)
	fmt.Printf("平均分: %.1f\n", float64(total)/float64(count))
	fmt.Println("最高分:", best, bestName)
}

